CREATE TABLE IF NOT EXISTS wb_settings (id TEXT PRIMARY KEY CHECK(id='simulation'),version INTEGER NOT NULL,policy_json TEXT NOT NULL CHECK(json_valid(policy_json)),updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wb_runs (id TEXT PRIMARY KEY,incident_id TEXT REFERENCES incidents(id),zone_id TEXT NOT NULL,user_id TEXT NOT NULL,private_user_id TEXT,kind TEXT NOT NULL,provider TEXT NOT NULL,model_id TEXT NOT NULL,status TEXT NOT NULL,started_at TEXT NOT NULL,ended_at TEXT,stop_reason TEXT,usage_json TEXT NOT NULL DEFAULT '{}',result_json TEXT,expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS wb_runs_zone_time ON wb_runs(zone_id,started_at);
CREATE TABLE IF NOT EXISTS wb_tools (id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES wb_runs(id) ON DELETE CASCADE,zone_id TEXT NOT NULL,name TEXT NOT NULL,args_json TEXT NOT NULL,args_digest TEXT NOT NULL,result_json TEXT NOT NULL,result_digest TEXT NOT NULL,status TEXT NOT NULL,latency_ms INTEGER NOT NULL,observed_at TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS wb_tools_run ON wb_tools(run_id);
CREATE TABLE IF NOT EXISTS wb_proposals (id TEXT PRIMARY KEY,incident_id TEXT NOT NULL REFERENCES incidents(id),run_id TEXT NOT NULL REFERENCES wb_runs(id),zone_id TEXT NOT NULL,requested_by TEXT NOT NULL,policy_version INTEGER NOT NULL,proposal_json TEXT NOT NULL,status TEXT NOT NULL,decision_reason TEXT NOT NULL,created_at TEXT NOT NULL,approval_deadline TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS wb_proposals_zone ON wb_proposals(zone_id,created_at);
CREATE TABLE IF NOT EXISTS wb_approvals (id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL UNIQUE REFERENCES wb_proposals(id),actor_id TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN ('approve','reject')),reason TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wb_executions (id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL UNIQUE REFERENCES wb_proposals(id),zone_id TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,executor_type TEXT NOT NULL CHECK(executor_type='simulation-only'),resource_id TEXT NOT NULL,status TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL,created_at TEXT NOT NULL,rule_expires_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wb_rules (id TEXT PRIMARY KEY,execution_id TEXT NOT NULL UNIQUE REFERENCES wb_executions(id),zone_id TEXT NOT NULL,owner TEXT NOT NULL CHECK(owner='example-soc-simulation'),config_json TEXT NOT NULL,config_digest TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN (0,1)),expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wb_verifications (id TEXT PRIMARY KEY,execution_id TEXT NOT NULL REFERENCES wb_executions(id),result TEXT NOT NULL,metrics_json TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wb_history (id TEXT PRIMARY KEY,target_id TEXT NOT NULL,zone_id TEXT NOT NULL,state TEXT NOT NULL,details_json TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wb_threads (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,zone_id TEXT NOT NULL,incident_id TEXT REFERENCES incidents(id),created_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wb_messages (id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES wb_threads(id) ON DELETE CASCADE,role TEXT NOT NULL,content TEXT NOT NULL,run_id TEXT REFERENCES wb_runs(id),created_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wb_simulations (id TEXT PRIMARY KEY,suite_id TEXT,scenario_id TEXT NOT NULL,incident_id TEXT NOT NULL REFERENCES incidents(id),run_id TEXT REFERENCES wb_runs(id),zone_id TEXT NOT NULL,user_id TEXT NOT NULL,status TEXT NOT NULL,evaluation_json TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wb_budget (month TEXT NOT NULL,provider TEXT NOT NULL,spent_micro INTEGER NOT NULL DEFAULT 0,reserved_micro INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(month,provider));
CREATE TABLE IF NOT EXISTS wb_reservations (id TEXT PRIMARY KEY REFERENCES wb_runs(id) ON DELETE CASCADE,month TEXT NOT NULL,provider TEXT NOT NULL,reserved_micro INTEGER NOT NULL,settled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS wb_limits (id TEXT PRIMARY KEY,n INTEGER NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wb_guards (id TEXT PRIMARY KEY,valid INTEGER NOT NULL CHECK(valid=1));

CREATE TABLE IF NOT EXISTS wb_maintenance (id TEXT PRIMARY KEY,updated_at TEXT NOT NULL,details_json TEXT NOT NULL);
